window.api=async function(path,options={}){const response=await fetch('/api'+path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});let body={};try{body=await response.json()}catch{}if(!response.ok)throw new Error(body.error||`Request failed (${response.status})`);return body};
(async()=>{try{const {user}=await api('/me');const all=store.get('cs_users',{});all[user.email]=user;store.set('cs_users',all);store.set('cs_session',user.email);const [{attempts},{interviews}]=await Promise.all([api('/attempts'),api('/interviews')]);store.set('cs_att_'+user.email,attempts);store.set('cs_int_'+user.email,interviews);const script=document.createElement('script');script.src='js/app.js';document.body.appendChild(script);}catch{location.replace('login.html')}})();
